1	'use strict';
2	
3	const { createHash } = require('node:crypto');
4	const { ConflictError, IntegrityError, NotFoundError, ValidationError } = require('./errors');
5	const replay = require('./replay');
6	const { ReplayReader, ReplayWriter, VerifyReplay } = require('./replaystream');
7	const sim = require('./sim');
8	const { Store } = require('./store');
9	
10	/** Canonical JSON used to compare an idempotent retry with the original request. */
11	function canonicalJson(value) {
12	  if (Array.isArray(value)) {
13	    return `[${value.map(canonicalJson).join(',')}]`;
14	  }
15	  if (value && typeof value === 'object') {
16	    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
17	  }
18	  return JSON.stringify(value === undefined ? null : value);
19	}
20	
21	function requestHash(body) {
22	  return createHash('sha256').update(canonicalJson(body)).digest('hex');
23	}
24	
25	/** A spectator stream may trail the live frontier by at most this many ticks. */
26	const MAX_SPECTATOR_DELAY = 1024;
27	
28	/**
29	 * LockstepNet service: deterministic lockstep simulation with rollback replay.
30	 *
31	 * The whole contract follows from three rules:
32	 *   1. a match state is a pure function of (configuration, set of input records);
33	 *   2. an input record is keyed by (tick, unit, command) and applied in a
34	 *      canonical order inside its tick, so arrival order is irrelevant;
35	 *   3. an input for a tick that already ran forces a rollback: the frames from
36	 *      that tick on are rebuilt by replaying the stored input log, which
37	 *      reproduces the hashes that were recorded before the rollback.
38	 */
39	class Lockstep {
40	  constructor(database) {
41	    this.store = new Store(database);
42	  }
43	
44	  close() {
45	    this.store.close();
46	  }
47	
48	  /** Required-key idempotency: repeats return the first result, conflicts are 409. */
49	  idempotent(key, operation, body, action) {
50	    if (typeof key !== 'string' || key.length === 0 || key.length > 200) {
51	      throw new ValidationError('Idempotency-Key header must be a non-empty string of at most 200 characters');
52	    }
53	    const hash = requestHash(body);
54	    return this.store.transaction(() => {
55	      const existing = this.store.getIdempotent(key);
56	      if (existing) {
57	        if (existing.operation !== operation) {
58	          throw new ConflictError('idempotency key was already used for another operation');
59	        }
60	        if (existing.requestHash !== hash) {
61	          throw new ConflictError('idempotency key was already used with a different request body');
62	        }
63	        return existing.response;
64	      }
65	      const response = action();
66	      this.store.putIdempotent(key, operation, hash, response);
67	      return response;
68	    });
69	  }
70	
71	  match(matchId) {
72	    const record = this.store.readMatch(matchId);
73	    if (!record) {
74	      throw new NotFoundError(`match ${matchId} was not found`);
75	    }
76	    return record;
77	  }
78	
79	  config(matchId) {
80	    return this.match(matchId).config;
81	  }
82	
83	  createMatch(raw, key) {
84	    const config = sim.parseConfig(raw);
85	    return this.idempotent(key, `create-match:${config.id}`, raw, () => {
86	      if (this.store.readMatch(config.id)) {
87	        throw new ConflictError(`match ${config.id} already exists`);
88	      }
89	      const state = sim.initialState(config);
90	      state.hash = sim.stateHash(state);
91	      this.store.insertMatch(config, state);
92	      return this.describe(config, state);
93	    });
94	  }
95	
96	  getState(matchId) {
97	    const record = this.match(matchId);
98	    return this.describe(record.config, this.store.readState(matchId));
99	  }
100	
101	  /**
102	   * Public projection of a match: configuration, current deterministic state and
103	   * input-delivery counters.
104	   *
105	   * `missing` counts the input records the match expected but never received:
106	   * one per unit alive at the start of each already simulated tick, minus the
107	   * records that were delivered for that tick.
108	   */
109	  describe(config, state) {
110	    const frames = this.store.readFrames(config.id);
111	    const stats = this.store.readStats(config.id);
112	    let missing = 0;
113	    let settled = 0;
114	    for (const frame of frames) {
115	      const gap = Math.max(0, frame.alive - frame.inputs.length);
116	      missing += gap;
117	      settled += gap === 0 ? 1 : 0;
118	    }
119	    const alive = Object.values(state.units).filter((unit) => unit.health > 0);
120	    const team = (name) => ({ alive: alive.filter((unit) => unit.team === name).length, damage: state.teamDamage[name] });
121	    return {
122	      config: { id: config.id, max_ticks: config.maxTicks, seed: config.seed, units: config.units },
123	      inputs: {
124	        accepted: stats.accepted, duplicates: stats.duplicates, missing,
125	        rejected: stats.rejected, rollbacks: stats.rollbacks, settled,
126	      },
127	      match_id: config.id,
128	      max_ticks: config.maxTicks,
129	      seed: config.seed,
130	      state_hash: state.hash,
131	      status: state.status,
132	      teams: { blue: team('blue'), red: team('red') },
133	      tick: state.tick,
134	      units: Object.values(state.units).sort((left, right) => (left.id < right.id ? -1 : 1)).map((unit) => ({
135	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
136	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
137	      })),
138	    };
139	  }
140	
141	  /**
142	   * Queue input records. Records may arrive in any order, any number of times
143	   * and any number per request.
144	   *
145	   *  - a record whose (tick, unit, command) key is already stored is a
146	   *    duplicate: counted, never re-applied, and it cannot change the state;
147	   *  - a record for a tick beyond the frontier is stored for later;
148	   *  - a record for a tick at or below the frontier triggers one rollback to the
149	   *    earliest such tick, then a recomputation back to the frontier;
150	   *  - a record for an unknown unit, an out-of-range tick or a malformed command
151	   *    is rejected with a reason and leaves the state untouched.
152	   */
153	  submitInputs(matchId, raw, key) {
154	    const record = this.match(matchId);
155	    sim.exactKeys(raw, ['inputs'], 'body');
156	    if (!Array.isArray(raw.inputs)) {
157	      throw new ValidationError('inputs must be an array');
158	    }
159	    return this.idempotent(key, `submit-inputs:${matchId}`, raw, () => {
160	      if (raw.inputs.length === 0) {
161	        throw new ValidationError('inputs must be a non-empty array');
162	      }
163	      return this.processInputs(record, raw.inputs);
164	    });
165	  }
166	
167	  /**
168	   * The input pipeline shared by the match-wide and the session-scoped input
169	   * endpoints: validation, de-duplication, stat accounting and the single
170	   * rollback-and-rebuild pass for late records. When `options.session` is set, a
171	   * record whose unit is not bound to that session is rejected with
172	   * `wrong_session` instead of being applied; the global rules, ordering and
173	   * counters stay identical.
174	   */
175	  processInputs(record, entries, options = {}) {
176	    const matchId = record.config.id;
177	    const session = options.session || null;
178	    const frontier = this.store.readState(matchId).tick;
179	    const accepted = [];
180	    const duplicates = [];
181	    const rejected = [];
182	    let earliest = null;
183	    entries.forEach((entry, index) => {
184	      let input;
185	      try {
186	        input = sim.parseInputRecord(entry);
187	      } catch (error) {
188	        rejected.push({ index, message: error.message, reason: 'invalid_input' });
189	        return;
190	      }
191	      if (input.tick >= record.config.maxTicks) {
192	        rejected.push({
193	          index,
194	          message: `input tick ${input.tick} is outside the match length ${record.config.maxTicks}`,
195	          reason: 'out_of_range',
196	        });
197	        return;
198	      }
199	      if (!record.config.units.some((unit) => unit.id === input.unit)) {
200	        rejected.push({ index, message: `input references unknown unit ${input.unit}`, reason: 'unknown_unit' });
201	        return;
202	      }
203	      if (session && !session.units.includes(input.unit)) {
204	        rejected.push({
205	          index,
206	          message: `unit ${input.unit} does not belong to session ${session.id}`,
207	          reason: 'wrong_session',
208	        });
209	        return;
210	      }
211	      if (this.store.readInput(matchId, input.tick, input.unit, input.command.kind)) {
212	        duplicates.push({ command: input.command.kind, tick: input.tick, unit: input.unit });
213	        return;
214	      }
215	      input.arrival = this.store.countInputsBefore(matchId, record.config.maxTicks);
216	      this.store.insertInput(matchId, input, sim.stripInput(input));
217	      accepted.push({ command: input.command.kind, seq: input.seq, tick: input.tick, unit: input.unit });
218	      if (earliest === null || input.tick < earliest) {
219	        earliest = input.tick;
220	      }
221	    });
222	
223	    this.store.bumpStat(matchId, 'accepted', accepted.length);
224	    this.store.bumpStat(matchId, 'duplicates', duplicates.length);
225	    this.store.bumpStat(matchId, 'rejected', rejected.length);
226	
227	    let rollback = null;
228	    if (earliest !== null && earliest < frontier) {
229	      // A late input rewinds the match to the earliest affected tick and then
230	      // replays forward to the frontier it had reached before this request, so
231	      // accepting a late input never loses already simulated ticks.
232	      const rewound = this.rollback(matchId, earliest);
233	      const { frames } = this.resimulate(matchId, earliest, frontier, false);
234	      const after = this.store.readState(matchId);
235	      this.store.bumpStat(matchId, 'rollbacks', 1);
236	      rollback = { ...rewound, frames_recomputed: frames.length, hash_after: after.hash, tick: after.tick };
237	    }
238	    return {
239	      ...this.describe(record.config, this.store.readState(matchId)),
240	      accepted, duplicates, rejected, rollback,
241	    };
242	  }
243	
244	  /** Load a match's session or fail with 404; never returns null. */
245	  requireSession(matchId, sessionId) {
246	    this.match(matchId);
247	    const session = this.store.readSession(matchId, sessionId);
248	    if (!session) {
249	      throw new NotFoundError(`session ${sessionId} of match ${matchId} was not found`);
250	    }
251	    return session;
252	  }
253	
254	  describeSession(matchId, session) {
255	    return {
256	      match_id: matchId,
257	      session_id: session.id,
258	      status: session.status,
259	      units: session.units.slice(),
260	    };
261	  }
262	
263	  /**
264	   * Bind a session to one or more match units. Units must be a non-empty list of
265	   * distinct units of this match, and no unit may belong to another session, so
266	   * ownership is unique. Sessions are bookkeeping only: they never enter the
267	   * state hash or the replay document.
268	   */
269	  createSession(matchId, raw, key) {
270	    const record = this.match(matchId);
271	    sim.exactKeys(raw, ['id', 'units'], 'body');
272	    if (raw.id === undefined || raw.units === undefined) {
273	      throw new ValidationError('body must contain id and units');
274	    }
275	    const sessionId = sim.identifier(raw.id, 'session id');
276	    if (!Array.isArray(raw.units) || raw.units.length === 0) {
277	      throw new ValidationError('units must be a non-empty array');
278	    }
279	    const units = [];
280	    const seen = new Set();
281	    for (const entry of raw.units) {
282	      const unitId = sim.identifier(entry, 'session unit id');
283	      if (seen.has(unitId)) {
284	        throw new ValidationError(`session units must be unique: ${unitId}`);
285	      }
286	      seen.add(unitId);
287	      if (!record.config.units.some((unit) => unit.id === unitId)) {
288	        throw new ValidationError(`session references unknown unit ${unitId}`);
289	      }
290	      units.push(unitId);
291	    }
292	    units.sort();
293	    return this.idempotent(key, `create-session:${matchId}`, raw, () => {
294	      if (this.store.readSession(matchId, sessionId)) {
295	        throw new ConflictError(`session ${sessionId} already exists for match ${matchId}`);
296	      }
297	      for (const other of this.store.readSessions(matchId)) {
298	        const overlap = other.units.find((unitId) => seen.has(unitId));
299	        if (overlap) {
300	          throw new ConflictError(`unit ${overlap} already belongs to session ${other.id}`);
301	        }
302	      }
303	      const session = { id: sessionId, status: 'connected', units };
304	      this.store.insertSession(matchId, session);
305	      return this.describeSession(matchId, session);
306	    });
307	  }
308	
309	  /**
310	   * Submit inputs through a session. The format, de-duplication key, canonical
311	   * order, late-input rollback and counters are exactly those of the match-wide
312	   * endpoint; an input for a unit the session does not own is rejected with
313	   * reason `wrong_session`, and a disconnected session may not submit at all.
314	   */
315	  submitSessionInputs(matchId, sessionId, raw, key) {
316	    const session = this.requireSession(matchId, sessionId);
317	    sim.exactKeys(raw, ['inputs'], 'body');
318	    if (!Array.isArray(raw.inputs)) {
319	      throw new ValidationError('inputs must be an array');
320	    }
321	    return this.idempotent(key, `submit-session-inputs:${matchId}:${sessionId}`, raw, () => {
322	      if (session.status === 'disconnected') {
323	        throw new ConflictError(`session ${sessionId} is disconnected and cannot submit inputs`);
324	      }
325	      if (raw.inputs.length === 0) {
326	        throw new ValidationError('inputs must be a non-empty array');
327	      }
328	      return this.processInputs(this.match(matchId), raw.inputs, { session });
329	    });
330	  }
331	
332	  /** Mark a session disconnected; the match itself is unaffected. Idempotent. */
333	  disconnectSession(matchId, sessionId, raw, key) {
334	    const session = this.requireSession(matchId, sessionId);
335	    const body = raw === undefined || raw === null ? {} : raw;
336	    sim.exactKeys(body, [], 'body');
337	    return this.idempotent(key, `disconnect-session:${matchId}:${sessionId}`, body, () => {
338	      if (session.status !== 'disconnected') {
339	        this.store.setSessionStatus(matchId, sessionId, 'disconnected');
340	      }
341	      return this.describeSession(matchId, { ...session, status: 'disconnected' });
342	    });
343	  }
344	
345	  /**
346	   * Reconnect a session and stream the frames recorded *after* `after_tick`, at
347	   * most `limit` per call (default and maximum 1024), together with the
348	   * caught-up unit states and team damage. The session ends up `connected`; a
349	   * partial window reports `complete: false` and is paged by calling again with
350	   * the returned `next_tick`.
351	   *
352	   * The window is read from the recorded frame log and must be contiguous and
353	   * hash-consistent end to end; a gap or a recomputation mismatch is an
354	   * `integrity_failure` instead of an inconsistent catch-up.
355	   */
356	  resumeSession(matchId, sessionId, raw, key) {
357	    const session = this.requireSession(matchId, sessionId);
358	    sim.exactKeys(raw, ['after_tick', 'limit'], 'body');
359	    if (!Object.prototype.hasOwnProperty.call(raw, 'after_tick')) {
360	      throw new ValidationError('body must contain after_tick');
361	    }
362	    const afterTick = raw.after_tick;
363	    if (!Number.isInteger(afterTick) || afterTick < 0) {
364	      throw new ValidationError('after_tick must be a non-negative integer');
365	    }
366	    const limit = raw.limit === undefined ? sim.MAX_STEP : raw.limit;
367	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
368	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
369	    }
370	    return this.idempotent(key, `resume-session:${matchId}:${sessionId}`, raw, () => {
371	      const frontier = this.store.readState(matchId).tick;
372	      if (afterTick > frontier) {
373	        throw new ConflictError(`after_tick ${afterTick} is past the current tick ${frontier}`);
374	      }
375	      const frames = this.sessionFrames(matchId, afterTick, limit, frontier);
376	      if (session.status !== 'connected') {
377	        this.store.setSessionStatus(matchId, sessionId, 'connected');
378	      }
379	      const state = this.store.readState(matchId);
380	      const reached = afterTick + frames.length;
381	      const complete = reached >= frontier;
382	      const units = this.unitsAt(matchId, session.units, reached, state)
383	        .sort((left, right) => (left.id < right.id ? -1 : 1));
384	      return {
385	        complete,
386	        frames,
387	        match_id: matchId,
388	        next_tick: reached,
389	        session_id: sessionId,
390	        state_hash: complete ? state.hash : this.frameHashAt(matchId, reached),
391	        status: 'connected',
392	        team_damage: this.teamDamageAt(matchId, reached, state),
393	        units,
394	      };
395	    });
396	  }
397	
398	  /**
399	   * The recorded frame summaries strictly after `afterTick`, up to `limit`, in
400	   * tick order. The log must be contiguous from the requested point; the window
401	   * is re-derived in memory from the snapshot before it and must reproduce every
402	   * recorded hash - a divergence is an integrity failure rather than a silently
403	   * different catch-up. Nothing here mutates the frame log.
404	   */
405	  sessionFrames(matchId, afterTick, limit, frontier) {
406	    const end = Math.min(afterTick + limit, frontier);
407	    const byTick = new Map();
408	    for (const frame of this.store.readFramesFrom(matchId, afterTick + 1)) {
409	      byTick.set(frame.tick, frame);
410	    }
411	    const frames = [];
412	    for (let tick = afterTick + 1; tick <= end; tick += 1) {
413	      const frame = byTick.get(tick);
414	      if (!frame) {
415	        // Every tick up to the frontier must have a frame; a gap means the log
416	        // was corrupted and catch-up cannot be served continuously.
417	        throw new IntegrityError(`match ${matchId} is missing recorded frame ${tick}`);
418	      }
419	      frames.push({
420	        casualties: frame.delta.casualties, settled: frame.settled,
421	        state_hash: frame.state_hash, tick: frame.tick,
422	      });
423	    }
424	    if (frames.length > 0) {
425	      this.verifyWindow(matchId, afterTick, frames);
426	    }
427	    return frames;
428	  }
429	
430	  /**
431	   * Recompute the frames of a catch-up window in memory from the snapshot before
432	   * it and the stored input log, comparing each hash with the recorded one. This
433	   * is the read-only counterpart of the rollback rebuild: session catch-up never
434	   * trims or rewrites the frame log.
435	   */
436	  verifyWindow(matchId, afterTick, frames) {
437	    const state = this.snapshotAt(matchId, afterTick);
438	    const buckets = new Map();
439	    for (const input of this.store.readInputs(matchId)) {
440	      const bucket = buckets.get(input.tick);
441	      if (bucket) {
442	        bucket.push(input.body);
443	      } else {
444	        buckets.set(input.tick, [input.body]);
445	      }
446	    }
447	    for (const bucket of buckets.values()) {
448	      bucket.sort(sim.compareInputs);
449	    }
450	    for (const frame of frames) {
451	      const settled = buckets.get(state.tick) || [];
452	      sim.applyTick(state, settled);
453	      state.hash = sim.stateHash(state);
454	      if (state.tick !== frame.tick || state.hash !== frame.state_hash) {
455	        throw new IntegrityError(`frame ${frame.tick} of match ${matchId} does not recompute to its recorded hash`);
456	      }
457	    }
458	  }
459	
460	  /** Hash of the state *after* frame `tick`; 0 is the initial (frontier) hash. */
461	  frameHashAt(matchId, tick) {
462	    if (tick <= 0) {
463	      return sim.stateHash(sim.initialState(this.config(matchId)));
464	    }
465	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
466	    if (!frame) {
467	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
468	    }
469	    return frame.state_hash;
470	  }
471	
472	  /** Team damage at frame `tick`, taken from the frame snapshot when mid-window. */
473	  teamDamageAt(matchId, tick, current) {
474	    if (tick >= current.tick) {
475	      return { blue: current.teamDamage.blue, red: current.teamDamage.red };
476	    }
477	    if (tick <= 0) {
478	      return { blue: 0, red: 0 };
479	    }
480	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
481	    if (!frame) {
482	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
483	    }
484	    return { blue: frame.state.teams.blue, red: frame.state.teams.red };
485	  }
486	
487	  /** Snapshots of the session-owned units as they are at frame `tick`. */
488	  unitsAt(matchId, unitIds, tick, current) {
489	    let source;
490	    if (tick >= current.tick) {
491	      source = current.units;
492	    } else if (tick <= 0) {
493	      source = sim.initialState(this.config(matchId)).units;
494	    } else {
495	      const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
496	      if (!frame) {
497	        throw new IntegrityError(`match ${matchId} has no recorded frame ${tick}`);
498	      }
499	      source = {};
500	      for (const unit of frame.state.units) {
501	        source[unit.id] = unit;
502	      }
503	    }
504	    return unitIds.map((id) => {
505	      const unit = source[id];
506	      if (!unit) {
507	        throw new IntegrityError(`frame ${tick} of match ${matchId} is missing unit ${id}`);
508	      }
509	      return {
510	        alive: unit.health > 0, attacking: unit.attacking, health: unit.health,
511	        id: unit.id, position: unit.position, team: unit.team, velocity: unit.velocity,
512	      };
513	    });
514	  }
515	
516	  /** Load a match's spectator or fail with 404; never returns null. */
517	  requireSpectator(matchId, spectatorId) {
518	    this.match(matchId);
519	    const spectator = this.store.readSpectator(matchId, spectatorId);
520	    if (!spectator) {
521	      throw new NotFoundError(`spectator ${spectatorId} of match ${matchId} was not found`);
522	    }
523	    return spectator;
524	  }
525	
526	  /**
527	   * The frame a spectator may currently see: the frontier delayed by
528	   * `delay_ticks` while a match runs, or the final tick once it has ended. A
529	   * finished match is frozen, so its spectators catch up to the very end instead
530	   * of trailing forever.
531	   */
532	  visibleTick(spectator, state) {
533	    if (state.status !== 'running') {
534	      return state.tick;
535	    }
536	    return Math.max(0, state.tick - spectator.delayTicks);
537	  }
538	
539	  /**
540	   * Register a spectator: a passive reader that trails the live frontier by
541	   * `delay_ticks`. Spectators are bookkeeping only: creating one never advances
542	   * the match and never enters a `state_hash` or `replay_hash`.
543	   */
544	  createSpectator(matchId, raw, key) {
545	    const record = this.match(matchId);
546	    sim.exactKeys(raw, ['id', 'delay_ticks'], 'body');
547	    if (raw.id === undefined || raw.delay_ticks === undefined) {
548	      throw new ValidationError('body must contain id and delay_ticks');
549	    }
550	    const spectatorId = sim.identifier(raw.id, 'spectator id');
551	    const delayTicks = sim.integer(raw.delay_ticks, 'delay_ticks', 0, MAX_SPECTATOR_DELAY);
552	    return this.idempotent(key, `create-spectator:${matchId}`, raw, () => {
553	      if (this.store.readSpectator(matchId, spectatorId)) {
554	        throw new ConflictError(`spectator ${spectatorId} already exists for match ${matchId}`);
555	      }
556	      const spectator = { delayTicks, highWater: 0, id: spectatorId, maxDelivered: 0, reset: false };
557	      this.store.insertSpectator(matchId, spectator);
558	      const state = this.store.readState(matchId);
559	      return {
560	        delay_ticks: delayTicks,
561	        match_id: matchId,
562	        spectator_id: spectatorId,
563	        visible_tick: this.visibleTick(spectator, state),
564	      };
565	    });
566	  }
567	
568	  /**
569	   * Poll a spectator's delayed stream.
570	   *
571	   * In normal `stream` mode the response carries the contiguous recorded frames
572	   * strictly after `after_tick` up to the spectator's `visible_tick`, at most
573	   * `limit` frames, followed by the state at the end of the returned window.
574	   * `complete` is true only when the window reached `visible_tick`.
575	   *
576	   * When a rollback (a late input or the explicit endpoint) rewrites a frame the
577	   * spectator had already received, the spectator is marked for reset: the next
578	   * poll ignores `after_tick`, replays from tick 0 in pages of `limit`, and
579	   * reports `mode: "reset"` until the reset stream catches back up.
580	   */
581	  pollSpectator(matchId, spectatorId, raw, key) {
582	    const spectator = this.requireSpectator(matchId, spectatorId);
583	    sim.exactKeys(raw, ['after_tick', 'limit'], 'body');
584	    const afterTick = raw.after_tick === undefined ? 0 : raw.after_tick;
585	    if (!Number.isInteger(afterTick) || afterTick < 0) {
586	      throw new ValidationError('after_tick must be a non-negative integer');
587	    }
588	    const limit = raw.limit === undefined ? sim.MAX_STEP : raw.limit;
589	    if (!Number.isInteger(limit) || limit < 1 || limit > sim.MAX_STEP) {
590	      throw new ValidationError(`limit must be an integer between 1 and ${sim.MAX_STEP}`);
591	    }
592	    return this.idempotent(key, `poll-spectator:${matchId}:${spectatorId}`, raw, () => {
593	      const state = this.store.readState(matchId);
594	      const visible = this.visibleTick(spectator, state);
595	      if (!spectator.reset && afterTick > visible) {
596	        throw new ConflictError(`after_tick ${afterTick} is past the visible tick ${visible}`);
597	      }
598	
599	      let mode = 'stream';
600	      let startTick = afterTick;
601	      if (spectator.reset) {
602	        // A reset replays the whole history from tick 0 in limit-sized pages;
603	        // after_tick from the client is discarded. The spectator's high-water
604	        // mark, rewound to 0 when the reset was flagged, is the paging cursor.
605	        mode = 'reset';
606	        startTick = spectator.highWater;
607	      }
608	
609	      const end = Math.min(startTick + limit, visible);
610	      const frames = this.spectatorFrames(matchId, startTick, end);
611	      const reached = startTick + frames.length;
612	
613	      let complete;
614	      let nextReset = spectator.reset;
615	      if (spectator.reset) {
616	        complete = reached >= visible;
617	        nextReset = !complete;
618	      } else {
619	        complete = reached >= visible;
620	      }
621	
622	      const updated = {
623	        ...spectator,
624	        highWater: reached,
625	        maxDelivered: Math.max(spectator.maxDelivered, reached),
626	        reset: nextReset,
627	      };
628	      this.store.writeSpectator(matchId, updated);
629	
630	      return {
631	        complete,
632	        frames,
633	        match_id: matchId,
634	        mode,
635	        next_tick: reached,
636	        spectator_id: spectatorId,
637	        state_hash: this.frameHashAt(matchId, reached),
638	        team_damage: this.teamDamageAt(matchId, reached, state),
639	        units: this.allUnitsAt(matchId, reached, state),
640	      };
641	    });
642	  }
643	
644	  /**
645	   * Contiguous recorded frames with ticks in `(startTick, endTick]`, each
646	   * re-derived from the snapshot before the window and checked against its
647	   * recorded hash. A gap or a recomputation mismatch is an `integrity_failure`
648	   * rather than an inconsistent stream.
649	   */
650	  spectatorFrames(matchId, startTick, endTick) {
651	    if (endTick <= startTick) {
652	      return [];
653	    }
654	    const byTick = new Map();
655	    for (const frame of this.store.readFramesFrom(matchId, startTick + 1)) {
656	      byTick.set(frame.tick, frame);
657	    }
658	    const frames = [];
659	    for (let tick = startTick + 1; tick <= endTick; tick += 1) {
660	      const frame = byTick.get(tick);
661	      if (!frame) {
662	        throw new IntegrityError(`match ${matchId} is missing recorded frame ${tick}`);
663	      }
664	      frames.push({
665	        casualties: frame.delta.casualties, settled: frame.settled,
666	        state_hash: frame.state_hash, tick: frame.tick,
667	      });
668	    }
669	    this.verifyWindow(matchId, startTick, frames);
670	    return frames;
671	  }
672	
673	  /** Every unit snapshot as it is at frame `tick`, sorted by unit id. */
674	  allUnitsAt(matchId, tick, current) {
675	    return this.unitsAt(
676	      matchId,
677	      this.config(matchId).units.map((unit) => unit.id),
678	      tick,
679	      current,
680	    ).sort((left, right) => (left.id < right.id ? -1 : left.id > right.id ? 1 : 0));
681	  }
682	
683	  /**
684	   * Advance a match by `count` ticks (default 1).
685	   *
686	   * The frontier never passes `max_ticks`, and the simulation stops early when a
687	   * team is eliminated. Advancing a match that is not `running` is a 409.
688	   */
689	  advance(matchId, raw, key) {
690	    const config = this.config(matchId);
691	    const body = raw === undefined || raw === null ? { count: 1 } : raw;
692	    sim.exactKeys(body, ['count'], 'body');
693	    const count = body.count === undefined ? 1 : body.count;
694	    if (!Number.isInteger(count) || count < 1 || count > sim.MAX_STEP) {
695	      throw new ValidationError(`count must be an integer between 1 and ${sim.MAX_STEP}`);
696	    }
697	    return this.idempotent(key, `advance:${matchId}`, { count }, () => {
698	      const before = this.store.readState(matchId);
699	      if (before.status !== 'running') {
700	        throw new ConflictError(`match ${matchId} is ${before.status} and cannot advance`);
701	      }
702	      const target = Math.min(before.tick + count, config.maxTicks);
703	      const { frames } = this.resimulate(matchId, before.tick, target, false);
704	      const updated = this.store.readState(matchId);
705	      return {
706	        ...this.describe(config, updated),
707	        advanced: frames.length,
708	        frames: frames.map((frame) => ({
709	          casualties: frame.delta.casualties, settled: frame.settled,
710	          state_hash: frame.state_hash, tick: frame.tick,
711	        })),
712	        state_hash: updated.hash,
713	      };
714	    });
715	  }
716	
717	  /**
718	   * Explicit rollback: rewind the match to `tick` by discarding every frame after
719	   * it. Input records are never discarded, so the next `POST /tick` replays them
720	   * and reproduces exactly the hashes recorded before the rollback.
721	   */
722	  rollback(matchId, tick) {
723	    const record = this.match(matchId);
724	    if (!Number.isInteger(tick) || tick < 0 || tick > record.config.maxTicks) {
725	      throw new ValidationError(`tick must be an integer between 0 and ${record.config.maxTicks}`);
726	    }
727	    const before = this.store.readState(matchId);
728	    if (tick > before.tick) {
729	      throw new ConflictError(`tick ${tick} is past the current tick ${before.tick}`);
730	    }
731	    this.resimulate(matchId, tick, tick, false);
732	    const after = this.store.readState(matchId);
733	    return {
734	      frames_recomputed: before.tick - tick,
735	      from_tick: before.tick, hash_after: after.hash, hash_before: before.hash,
736	      match_id: matchId, tick: after.tick, to_tick: tick,
737	    };
738	  }
739	
740	  /** The whole match as a portable replay document. */
741	  replayFile(matchId) {
742	    const record = this.match(matchId);
743	    const frames = this.store.readFrames(matchId).map((frame) => ({
744	      delta: frame.delta, settled: frame.settled, settled_inputs: frame.inputs,
745	      state_hash: frame.state_hash, tick: frame.tick,
746	    }));
747	    return replay.buildFile(record.config, frames, this.store.readInputs(matchId));
748	  }
749	
750	  /**
751	   * The determined match timeline as a self-describing replay byte stream.
752	   *
753	   * The stream records the format version, the tick configuration, the seed,
754	   * the start frame, the participant identifiers and the initial state hash,
755	   * followed by every confirmed frame with the inputs that were finally
756	   * applied (canonical JSON payloads, kept as raw bytes) and the resulting
757	   * state hash. Frames are committed in strictly ascending tick order, so the
758	   * exported bytes are a pure function of the initial conditions and the final
759	   * timeline: two matches whose inputs arrived in different orders but settled
760	   * to the same timeline export byte-identical streams.
761	   */
762	  replayStream(matchId) {
763	    const record = this.match(matchId);
764	    const config = record.config;
765	    const frames = this.store.readFrames(matchId);
766	    const writer = new ReplayWriter({
767	      initialStateHash: sim.stateHash(sim.initialState(config)),
768	      match: { id: config.id, max_ticks: config.maxTicks, seed: config.seed, units: config.units },
769	      startFrame: frames.length === 0 ? 1 : frames[0].tick,
770	    });
771	    for (const frame of frames) {
772	      writer.appendFrame({
773	        inputs: frame.inputs.map((canonical) => ({
774	          participant: JSON.parse(canonical).unit,
775	          payload: canonical,
776	        })),
777	        stateHash: frame.state_hash,
778	        tick: frame.tick,
779	      });
780	    }
781	    return writer.finalize();
782	  }
783	
784	  /**
785	   * Verify a replay byte stream in this process: re-simulate it from the
786	   * recorded initial conditions and compare every recorded state hash.
787	   */
788	  verifyReplayStream(source, options = {}) {
789	    return VerifyReplay(source, options);
790	  }
791	
792	  /**
793	   * `POST /matches/{id}/verify` accepts either `{"match_id": "..."}` to
794	   * re-simulate a stored match, or `{"replay": {...}}` for an uploaded replay.
795	   */
796	  verify(raw) {
797	    sim.exactKeys(raw, ['match_id', 'replay'], 'body');
798	    if (raw.replay !== undefined && raw.match_id !== undefined) {
799	      throw new ValidationError('provide either match_id or replay, not both');
800	    }
801	    if (raw.replay !== undefined) {
802	      return this.verifyDocument(raw.replay);
803	    }
804	    if (typeof raw.match_id !== 'string' || raw.match_id.length === 0) {
805	      throw new ValidationError('match_id must be a non-empty string');
806	    }
807	    return this.verifyDocument(this.replayFile(raw.match_id));
808	  }
809	
810	  verifyDocument(document) {
811	    const result = replay.verifyDocument(document);
812	    const stored = this.store.readMatch(result.config.id);
813	    const mismatches = result.mismatches.slice();
814	    let recordedHash = null;
815	    if (stored && stored.tick === result.state.tick) {
816	      recordedHash = stored.stateHash;
817	      if (recordedHash !== result.state_hash) {
818	        mismatches.push({
819	          kind: 'state_hash',
820	          message: 'replayed final state does not match the stored match state',
821	          recorded: recordedHash, recomputed: result.state_hash, tick: result.state.tick,
822	        });
823	      }
824	    }
825	    return {
826	      consistent: mismatches.length === 0,
827	      final_state_hash: result.state_hash,
828	      match_id: result.config.id,
829	      mismatches,
830	      recorded_state_hash: recordedHash,
831	      replay_hash: result.replay_hash,
832	      ticks_replayed: result.frames.length,
833	    };
834	  }
835	
836	  /**
837	   * Rebuild the frame log from `resumeTick` up to `targetTick`.
838	   *
839	   * Frames after `resumeTick` are discarded and re-derived from the snapshot at
840	   * `resumeTick` plus the stored input records. Every rebuilt frame that already
841	   * existed must keep its hash; a divergence means the log or the engine changed
842	   * and is reported as `integrity_failure` instead of silently changing results.
843	   *
844	   * `extend` lets the match simulate past `targetTick` until a team is eliminated
845	   * or `max_ticks` is reached. `POST /tick` does not extend: stopping exactly at
846	   * the requested tick is what makes rollback-then-advance reproduce hashes.
847	   */
848	  resimulate(matchId, resumeTick, targetTick, extend = false) {
849	    const config = this.config(matchId);
850	    if (targetTick < resumeTick) {
851	      throw new IntegrityError(`cannot resimulate ${matchId} backwards from ${resumeTick} to ${targetTick}`);
852	    }
853	    const expected = new Map();
854	    for (const frame of this.store.readFramesFrom(matchId, resumeTick + 1)) {
855	      expected.set(frame.tick, frame.state_hash);
856	    }
857	    // `resumeTick` is a *frame* number: resuming continues from the state that
858	    // frame recorded, and must read it before the log is trimmed.
859	    const state = this.snapshotAt(matchId, resumeTick);
860	    const resumeStatus = state.status;
861	    this.store.deleteFramesFrom(matchId, resumeTick + 1);
862	    // A spectator whose delayed stream already held a frame this rebuild
863	    // discards must restart from tick 0. A plain forward advance never reaches
864	    // this branch with such a spectator: its visible window lags the frontier,
865	    // so its high-water mark cannot pass the old frontier.
866	    for (const spectator of this.store.readSpectatorsPast(matchId, resumeTick)) {
867	      // Rewind the reset paging cursor to 0 so the replay restarts at tick 0.
868	      // The monotonic max-delivered mark is kept: it is what triggered this and
869	      // continues to describe how far this spectator has ever seen.
870	      spectator.highWater = 0;
871	      spectator.reset = true;
872	      this.store.writeSpectator(matchId, spectator);
873	    }
874	    const buckets = new Map();
875	    for (const input of this.store.readInputs(matchId)) {
876	      const bucket = buckets.get(input.tick);
877	      if (bucket) {
878	        bucket.push(input.body);
879	      } else {
880	        buckets.set(input.tick, [input.body]);
881	      }
882	    }
883	    for (const bucket of buckets.values()) {
884	      bucket.sort(sim.compareInputs);
885	    }
886	
887	    state.status = 'running';
888	    const boundary = extend ? config.maxTicks : targetTick;
889	    const rebuilt = [];
890	    let endedNaturally = false;
891	    // Iteration `produced` applies the inputs of tick `produced - 1` and records
892	    // frame `produced`.
893	    for (let produced = resumeTick + 1; produced <= boundary; produced += 1) {
894	      const aliveAtStart = Object.values(state.units).filter((unit) => unit.health > 0).length;
895	      const settled = buckets.get(state.tick) || [];
896	      const delta = sim.applyTick(state, settled);
897	      state.hash = sim.stateHash(state);
898	      const recorded = expected.get(state.tick);
899	      if (recorded !== undefined && recorded !== state.hash) {
900	        throw new IntegrityError(
901	          `frame ${state.tick} of match ${matchId} recomputed to ${state.hash} but was recorded as ${recorded}`,
902	        );
903	      }
904	      const frame = {
905	        alive: aliveAtStart,
906	        delta,
907	        inputs: settled.map(sim.canonicalInput),
908	        settled: settled.length >= aliveAtStart,
909	        state: {
910	          teams: { blue: state.teamDamage.blue, red: state.teamDamage.red },
911	          tick: state.tick,
912	          units: Object.values(state.units).map((unit) => ({
913	            attacking: unit.attacking, health: unit.health, id: unit.id,
914	            position: unit.position, team: unit.team, velocity: unit.velocity,
915	          })),
916	        },
917	        state_hash: state.hash,
918	        tick: state.tick,
919	      };
920	      this.store.insertFrame(matchId, frame);
921	      rebuilt.push(frame);
922	      if (state.status !== 'running') {
923	        endedNaturally = true;
924	        break;
925	      }
926	    }
927	    if (state.tick === targetTick && !endedNaturally) {
928	      // A timeline that stops exactly at the requested frontier keeps the status
929	      // that frontier had, instead of inventing one from the tick count.
930	      state.status = resumeStatus;
931	    }
932	    // The frontier hash is always the hash of the state the frontier holds, so a
933	    // rolled-back match reports the same hash that its frame held before.
934	    state.hash = sim.stateHash(state);
935	    this.store.writeState(matchId, state, {});
936	    return { frames: rebuilt, state };
937	  }
938	
939	  /**
940	   * State snapshot *after* frame `tick`: the initial state for tick 0, otherwise
941	   * the snapshot frame `tick` itself stored. A missing frame is a hard failure
942	   * because every later frame depends on it.
943	   */
944	  snapshotAt(matchId, tick) {
945	    const config = this.config(matchId);
946	    if (tick <= 0) {
947	      return sim.initialState(config);
948	    }
949	    const frame = this.store.readFrames(matchId).find((candidate) => candidate.tick === tick);
950	    if (!frame) {
951	      throw new IntegrityError(`match ${matchId} has no recorded frame ${tick} to resume from`);
952	    }
953	    const state = sim.initialState(config);
954	    state.teamDamage = { blue: frame.state.teams.blue, red: frame.state.teams.red };
955	    state.tick = frame.state.tick;
956	    for (const unit of frame.state.units) {
957	      state.units[unit.id] = { ...unit };
958	    }
959	    return state;
960	  }
961	}
962	
963	module.exports = { Lockstep, ReplayReader, ReplayWriter, VerifyReplay };
