126	 * Re-simulate a replay document from tick 0 and compare every recomputed state
127	 * hash with the recorded one. Inputs are applied in canonical order, so
128	 * shuffling the document's `inputs` array does not change the result.
129	 *
130	 * Returns { config, frames, mismatches, replay_hash, state, state_hash } where
131	 * `state_hash` is null as soon as any mismatch was found.
132	 */
133	function verifyDocument(raw) {
134	  const config = validateFile(raw);
135	  const buckets = groupInputs(config, raw.inputs);
136	  const state = sim.initialState(config);
137	  const mismatches = [];
