166	        recorded: frame.state_hash, recomputed: hash, tick: frame.tick,
167	      });
168	    }
169	    frames.push({ delta, state_hash: hash, tick: frame.tick });
170	  }
171	
172	  let replayHash = null;
173	  if (typeof raw.replay_hash === 'string') {
