179	        recorded: raw.replay_hash, recomputed: replayHash,
180	      });
181	    }
182	  }
183	  return {
184	    config, frames, mismatches, replay_hash: replayHash, state,
185	    state_hash: mismatches.length === 0 ? sim.stateHash(state) : null,
186	  };
187	}
