const dir = mkdtempSync(path.join(tmpdir(), 'snap-scratch-'));
const service = new Lockstep(path.join(dir, 'm.db'));

const config = {
  id: 'm', max_ticks: 40, seed: 1,
  units: [
    { id: 'blue-1', position: 0, team: 'blue', velocity: 0 },
    { id: 'red-1', position: 40, team: 'red', velocity: 0 },
  ],
};
service.createMatch(config, 'k1');
// red-1 attacks from tick 0 onward; blue-1 starts attacking at tick 2 (late-ish toggle)
service.submitInputs('m', { inputs: [
  { tick: 0, unit: 'red-1', command: { kind: 'attack', attacking: true } },
  { tick: 0, unit: 'blue-1', command: { by: 5, kind: 'move' } },
  { tick: 1, unit: 'blue-1', command: { kind: 'attack', attacking: true } },
  { tick: 3, unit: 'red-1', command: { kind: 'attack', attacking: false } },
] }, 'k2');
const adv = service.advance('m', { count: 8 }, 'k3');
const frontier = adv.tick;

// --- snapshot tick 0 = initial state ---
