service.createMatch({ id: 'late', max_ticks: 64, units: config.units.map((u) => ({ ...u })) }, 'l1');
service.submitInputs('late', { inputs: [
  { tick: 0, unit: 'red-1', command: { by: 3, kind: 'move' } },
