'use strict';
process.removeAllListeners('warning');
process.on('warning', () => {});

const assert = require('node:assert/strict');
const { mkdtempSync, rmSync } = require('node:fs');
const { tmpdir } = require('node:os');
const path = require('node:path');
const { Lockstep } = require('/mnt/d/alice16/alicet/wf16/t/2/task005/src/service');
const { ConflictError, IntegrityError, NotFoundError, ValidationError } = require('/mnt/d/alice16/alicet/wf16/t/2/task005/src/errors');

const dir = mkdtempSync(path.join(tmpdir(), 'snap-scratch-'));
const service = new Lockstep(path.join(dir, 'm.db'));

const config = {
  id: 'm', max_ticks: 40, seed: 1,
  units: [
    { id: 'blue-1', position: 0, team: 'blue', velocity: 0 },
    { id: 'red-1', position: 40, team: 'red', velocity: 0 },
  ],
};
service.createMatch(config, 'k1');
// red-1 attacks from tick 0 onward; blue-1 starts attacking at tick 2 (late-ish toggle)
service.submitInputs('m', { inputs: [
  { tick: 0, unit: 'red-1', command: { kind: 'attack', attacking: true } },
  { tick: 0, unit: 'blue-1', command: { by: 5, kind: 'move' } },
  { tick: 1, unit: 'blue-1', command: { kind: 'attack', attacking: true } },
  { tick: 3, unit: 'red-1', command: { kind: 'attack', attacking: false } },
] }, 'k2');
const adv = service.advance('m', { count: 8 }, 'k3');
const frontier = adv.tick;

// --- snapshot tick 0 = initial state ---
const s0 = service.getSnapshot('m', new URLSearchParams('tick=0'));
assert.equal(s0.match_id, 'm');
assert.equal(s0.tick, 0);
assert.equal(s0.status, 'running');
assert.deepEqual(s0.team_damage, { blue: 0, red: 0 });
assert.equal(s0.units.length, 2);
assert.equal(s0.units[0].id, 'blue-1'); // sorted by id
assert.equal(s0.units[0].attacking, false);
assert.match(s0.state_hash, /^[0-9a-f]{64}$/);

// snapshot at frontier equals current state hash
const sF = service.getSnapshot('m', new URLSearchParams(`tick=${frontier}`));
assert.equal(sF.state_hash, adv.state_hash);
assert.equal(sF.tick, frontier);
assert.deepEqual(sF.units, adv.units);

// --- deltas full page after 0 ---
const d = service.getDeltas('m', new URLSearchParams(`after_tick=0&limit=1024`));
assert.equal(d.match_id, 'm');
assert.equal(d.after_tick, 0);
assert.equal(d.base_state_hash, s0.state_hash);
assert.equal(d.next_tick, frontier);
assert.equal(d.complete, true);
assert.equal(d.deltas.length, frontier);
assert.deepEqual(d.deltas.map((x) => x.tick), [1, 2, 3, 4, 5, 6, 7, 8]);

// each delta fields
for (const e of d.deltas) {
  assert.match(e.state_hash, /^[0-9a-f]{64}$/);
  assert.equal(e.status, 'running');
  assert.equal(typeof e.settled, 'boolean');
  assert.ok(Array.isArray(e.casualties));
  assert.ok(Array.isArray(e.changed));
  // changed sorted by id
  const ids = e.changed.map((c) => c.id);
  assert.deepEqual(ids, [...ids].sort());
  // changed entry is a full public projection
  for (const c of e.changed) {
    assert.deepEqual(Object.keys(c), ['alive', 'attacking', 'health', 'id', 'position', 'team', 'velocity']);
  }
}

// tick 2: blue-1 toggles attacking true with no damage/position change -> must appear
const d2 = d.deltas[1];
assert.ok(d2.changed.some((c) => c.id === 'blue-1' && c.attacking === true), 'attacking-only change included');
// tick 4: red-1 toggles attacking false
const d4 = d.deltas[3];
assert.ok(d4.changed.some((c) => c.id === 'red-1' && c.attacking === false));

// hash chain matches recorded frames
d.deltas.forEach((e, i) => assert.equal(e.state_hash, adv.frames[i].state_hash));

// --- reduction property across pages ---
function reduce(baseUnits, deltas) {
  const byId = new Map(baseUnits.map((u) => [u.id, { ...u }]));
  for (const delta of deltas) {
    for (const c of delta.changed) byId.set(c.id, { ...(byId.get(c.id)), ...c });
  }
  return [...byId.values()].sort((a, b) => (a.id < b.id ? -1 : 1));
}
for (const limit of [1, 2, 3, 5]) {
  let after = 0;
  let units = s0.units;
  let baseHash = s0.state_hash;
  for (;;) {
    const page = service.getDeltas('m', new URLSearchParams(`after_tick=${after}&limit=${limit}`));
    assert.equal(page.base_state_hash, baseHash);
    units = reduce(units, page.deltas);
    after = page.next_tick;
    const snap = service.getSnapshot('m', new URLSearchParams(`tick=${after}`));
    assert.deepEqual(units, snap.units, `limit ${limit} at tick ${after}`);
    baseHash = snap.state_hash;
    if (page.complete) {
      assert.equal(after, frontier);
      break;
    }
  }
}

// empty page at frontier
const empty = service.getDeltas('m', new URLSearchParams(`after_tick=${frontier}`));
assert.equal(empty.next_tick, frontier);
assert.equal(empty.complete, true);
assert.deepEqual(empty.deltas, []);
assert.equal(empty.base_state_hash, adv.state_hash);

// default limit
assert.equal(service.getDeltas('m', new URLSearchParams('after_tick=0')).deltas.length, frontier);

// --- casualties: elimination match ---
service.createMatch({
  id: 'kill', max_ticks: 40, units: [
    { id: 'blue-1', position: 900, team: 'blue', velocity: 0 },
    { id: 'red-1', position: 100, team: 'red', velocity: 0 },
  ],
}, 'k4');
service.submitInputs('kill', { inputs: [
  { tick: 0, unit: 'blue-1', command: { kind: 'attack', attacking: true } },
  { tick: 0, unit: 'red-1', command: { kind: 'attack', attacking: true } },
] }, 'k5');
const kAdv = service.advance('kill', { count: 40 }, 'k6');
assert.notEqual(kAdv.status, 'running');
const kd = service.getDeltas('kill', new URLSearchParams('after_tick=0&limit=1024'));
const deathTick = kd.deltas.find((e) => e.casualties.length > 0);
assert.ok(deathTick, 'a casualty frame exists');
const deadChange = deathTick.changed.find((c) => deathTick.casualties.includes(c.id));
assert.ok(deadChange, 'the dying unit is in changed with full projection');
assert.equal(deadChange.alive, false);
assert.equal(deadChange.health, 0);
assert.equal(deadChange.attacking, false);
const kSnapEnd = service.getSnapshot('kill', new URLSearchParams(`tick=${kAdv.tick}`));
assert.equal(kSnapEnd.status, kAdv.status);
assert.deepEqual(reduce(kd.base_state_hash ? service.getSnapshot('kill', new URLSearchParams('tick=0')).units : [], kd.deltas), kSnapEnd.units);

// --- late input exposes only recomputed timeline ---
service.createMatch({ id: 'late', max_ticks: 64, units: config.units.map((u) => ({ ...u })) }, 'l1');
service.submitInputs('late', { inputs: [
  { tick: 0, unit: 'red-1', command: { by: 3, kind: 'move' } },
] }, 'l2');
service.advance('late', { count: 4 }, 'l3');
const beforeHash3 = service.getSnapshot('late', new URLSearchParams('tick=3')).state_hash;
service.submitInputs('late', { inputs: [
  { tick: 1, unit: 'blue-1', command: { kind: 'move', position: 777 } },
] }, 'l4');
const afterHash3 = service.getSnapshot('late', new URLSearchParams('tick=3')).state_hash;
assert.notEqual(afterHash3, beforeHash3, 'history reflects recomputation');
const lateD = service.getDeltas('late', new URLSearchParams('after_tick=0'));
assert.equal(lateD.deltas.find((e) => e.tick === 2).changed.some((c) => c.id === 'blue-1' && c.position === 777), true);

// --- explicit rollback: history truncated to current frontier; re-advance reproduces ---
const rb = service.rollback('late', 2);
assert.equal(service.getState('late').tick, 2);
assert.throws(() => service.getSnapshot('late', new URLSearchParams('tick=3')), ConflictError);
service.advance('late', { count: 2 }, 'l5');
// re-advanced frames reproduce the post-late-input hashes
const reAdv = service.getDeltas('late', new URLSearchParams('after_tick=2&limit=2'));
assert.equal(reAdv.deltas[0].state_hash, lateD.deltas[2].state_hash);
assert.equal(reAdv.deltas[1].state_hash, lateD.deltas[3].state_hash);
void rb;

// --- errors ---
const p = (s) => new URLSearchParams(s);
assert.throws(() => service.getSnapshot('missing', p('tick=0')), NotFoundError);
assert.throws(() => service.getDeltas('missing', p('after_tick=0')), NotFoundError);
for (const q of ['', 'tick=-1', 'tick=1.5', 'tick=abc', 'tick=true', 'tick=', 'bogus=1', 'tick=1&tick=2']) {
  assert.throws(() => service.getSnapshot('m', p(q)), (e) => e instanceof ValidationError, `snapshot ?${q}`);
}
for (const q of ['', 'after_tick=-1', 'after_tick=1.2', 'after_tick=x', 'limit=0', 'limit=1025', 'limit=a', 'limit=1.5', 'bogus=1', 'after_tick=1&after_tick=2']) {
  assert.throws(() => service.getDeltas('m', p(q)), (e) => e instanceof ValidationError, `deltas ?${q}`);
}
assert.throws(() => service.getSnapshot('m', p(`tick=${frontier + 1}`)), ConflictError);
assert.throws(() => service.getDeltas('m', p(`after_tick=${frontier + 1}`)), ConflictError);

// --- integrity failure on a tampered frame (service-level via store) ---
service.store.connection.prepare("UPDATE frames SET state_hash = ? WHERE match_id = 'm' AND tick = 2").run('f'.repeat(64));
assert.throws(() => service.getSnapshot('m', p('tick=2')), IntegrityError);
assert.throws(() => service.getSnapshot('m', p('tick=8')), IntegrityError);
assert.throws(() => service.getDeltas('m', p('after_tick=0')), IntegrityError);
// but unaffected history window 0..1 still works? rebuild replays all frames -> must fail
assert.throws(() => service.getSnapshot('m', p('tick=1')), IntegrityError);

// reads don't advance or change stats
const statsBefore = JSON.stringify(service.getState('m').inputs);
assert.throws(() => service.getSnapshot('m', p('tick=1')), IntegrityError);
assert.equal(JSON.stringify(service.getState('m').inputs), statsBefore);

service.close();
rmSync(dir, { recursive: true, force: true });
