/** Field-by-field comparison of two public unit projections. */
assertSameProjection(actual, expected, tick, matchId) {
  const shape = (units) => units.map((unit) => JSON.stringify(unit));
  assert.deepEqual(shape(actual), shape(expected),
    `deltas of match ${matchId} do not reduce to the snapshot at tick ${tick}`);
